'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');

function checkRange(tree, values, l, r) {
  const slice = values.slice(l, r);
  assert.equal(tree.sum(l, r), slice.reduce((sum, value) => sum + value, 0));
  assert.equal(tree.max(l, r), Math.max(...slice));
}

function checkSearch(tree, values, lo, x) {
  assert.equal(tree.firstAtLeast(lo, x), values.findIndex((value, i) => i >= lo && value >= x));
}

test('assignment discards ancestor and descendant addition tags', () => {
  for (const range of [[0, 8], [0, 4], [2, 6]]) {
    const values = [1, 2, 3, 4, 5, 6, 7, 8];
    const tree = new RangeTree(values);
    tree.add(0, 4, 9);
    tree.add(0, 8, 3);
    tree.assign(...range, -10);
    tree.add(...range, 2);
    for (let i = 0; i < values.length; i++) {
      values[i] += (i < 4 ? 9 : 0) + 3;
      if (i >= range[0] && i < range[1]) values[i] = -8;
    }
    checkRange(tree, values, 0, 8);
    checkSearch(tree, values, 0, -8);
    assert.deepEqual(tree.toArray(), values);
    for (let l = 0; l <= 8; l++) {
      for (let r = l; r <= 8; r++) checkRange(tree, values, l, r);
    }
  }
});

test('negative maxima and lazy threshold search', () => {
  const negative = new RangeTree([-5, -2, -7]);
  assert.equal(negative.max(0, 2), -2);
  assert.equal(negative.max(2, 3), -7);
  for (const operation of ['assign', 'add']) {
    const tree = new RangeTree([0, 0, 0, 0, 0]);
    tree[operation](0, 5, 5);
    assert.equal(tree.firstAtLeast(1, 5), 1);
    tree.assign(0, 5, -5);
    tree.add(2, 5, 10);
    assert.equal(tree.firstAtLeast(0, 5), 2);
    assert.equal(tree.firstAtLeast(3, 5), 3);
    assert.equal(tree.firstAtLeast(0, 6), -1);
    assert.equal(tree.firstAtLeast(5, -Infinity), -1);
    assert.equal(tree.firstAtLeast(0, Infinity), -1);
  }
});

test('seeded mixed operations agree with a plain array', () => {
  let seed = 0x51a9;
  const random = (limit) => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % limit;
  };
  for (const n of [1, 2, 3, 7, 8, 17, 31, 64]) {
    const values = Array.from({ length: n }, () => random(41) - 20);
    const tree = new RangeTree(values);
    for (let step = 0; step < 4000; step++) {
      let l = random(n + 1);
      let r = random(n + 1);
      if (l > r) [l, r] = [r, l];
      const value = random(101) - 50;
      const operation = random(10);
      if (operation < 7) {
        const assigning = operation < 3;
        assert.equal(tree[assigning ? 'assign' : 'add'](l, r, value), undefined);
        for (let i = l; i < r; i++) values[i] = assigning ? value : values[i] + value;
      } else if (operation === 7) {
        checkRange(tree, values, l, r);
      } else if (operation === 8) {
        checkSearch(tree, values, l, value);
      } else {
        const index = random(n);
        assert.equal(tree.get(index), values[index]);
      }
    }
    for (let l = 0; l <= n; l++) {
      for (let r = l; r <= n; r++) checkRange(tree, values, l, r);
      for (const x of [-Infinity, -100, -1, 0, 1, 100, Infinity]) checkSearch(tree, values, l, x);
    }
    assert.deepEqual(tree.toArray(), values);
  }
});

test('validation, empty ranges, read-only length, and independent arrays', () => {
  for (const input of [null, {}, [], [NaN], [Infinity], [-Infinity], ['1'], Array(2)]) {
    assert.throws(() => new RangeTree(input), RangeError);
  }
  const input = [3, -2, 7];
  const tree = new RangeTree(input);
  input[0] = 99;
  assert.equal(tree.length, 3);
  assert.throws(() => { tree.length = 0; }, TypeError);
  tree.add(0, 3, 4);
  const expected = [7, 2, 11];
  for (const [l, r] of [[-1, 2], [0, 4], [2, 1], [0.5, 2], [0, NaN], ['0', 2]]) {
    for (const operation of ['sum', 'max', 'assign', 'add']) {
      assert.throws(() => tree[operation](l, r, 9), RangeError);
    }
  }
  for (const value of [NaN, Infinity, -Infinity, '1', null, undefined]) {
    for (const operation of ['assign', 'add']) {
      assert.throws(() => tree[operation](0, 3, value), RangeError);
      assert.throws(() => tree[operation](2, 2, value), RangeError);
    }
  }
  for (const index of [-1, 3, 0.5, NaN, '0']) {
    assert.throws(() => tree.get(index), RangeError);
  }
  for (const lo of [-1, 4, 0.5, NaN, '0']) {
    assert.throws(() => tree.firstAtLeast(lo, 0), RangeError);
  }
  for (const x of [NaN, '0', null, undefined]) {
    assert.throws(() => tree.firstAtLeast(0, x), RangeError);
  }
  for (let i = 0; i <= 3; i++) {
    assert.equal(tree.assign(i, i, 100), undefined);
    assert.equal(tree.add(i, i, -100), undefined);
    assert.equal(tree.sum(i, i), 0);
    assert.equal(tree.max(i, i), -Infinity);
  }
