29:      throw new RangeError('values must be a nonempty array of finite numbers');
30:    }
31:    for (const value of values) {
32:      if (!Number.isFinite(value)) {
33:        throw new RangeError('values must be a nonempty array of finite numbers');
34:      }
35:    }
36:    this._length = values.length;
37:    const capacity = 4 * this._length;
38:    this._sums = new Float64Array(capacity);
39:    this._maxima = new Float64Array(capacity);
40:    this._assignments = new Float64Array(capacity);
41:    this._additions = new Float64Array(capacity);
42:    this._hasAssignment = new Uint8Array(capacity);
43:    this._build(1, 0, this._length, values);
44:  }
